1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="UTF-8">
5	<title>TMA: Tensor Memory Accelerator</title>
6	<link rel="stylesheet" href="../viz-base.css">
7	<script src="../viz-base.js"></script>
8	<style>
9	  .main { display:flex; gap:20px; max-width:1200px; margin:0 auto; align-items:center; justify-content:center;
10	    position:relative; }
11	  .mat-box { background:var(--surface); border-radius:10px; padding:14px; border:1px solid var(--border);
12	    box-shadow:0 1px 3px rgba(0,0,0,.06); text-align:center; }
13	  .mat-box h2 { font-size:14px; font-weight:700; margin-bottom:2px; }
14	  .mat-box .dims { font-size:11px; color:var(--dim); margin-bottom:6px; font-weight:600; }
15	
16	  .grid { display:inline-grid; gap:1px; }
17	
18	  /* Global memory cells */
19	  .gc {
20	    border-radius:2px; display:flex; align-items:center; justify-content:center;
21	    font-size:6px; font-weight:700; border:1.5px solid transparent; transition:all .12s;
22	    min-width:0; color:var(--text);
23	  }
24	  .gc.idle { background:#dde0e4; opacity:1; }
25	  .gc.inbox { background:var(--color-hover-bg); border-color:var(--accent); color:var(--color-hover-text);
26	    cursor:pointer; }
27	  .gc.hov { border-color:#222; border-width:2.5px; z-index:2; box-shadow:0 0 6px rgba(59,130,246,.4); }
28	
29	  /* Shared memory cells (swizzle-atom style) */
30	  .sc {
31	    border-radius:4px; display:flex; flex-direction:column; align-items:center; justify-content:center;
32	    font-weight:700; border:2.5px solid transparent; transition:all .18s;
33	    min-width:0; color:#fff; text-shadow:0 1px 1px rgba(0,0,0,.2); line-height:1.2; cursor:pointer;
34	  }
35	  .sc .cv { font-size:11px; }
36	  .sc .ca { font-size:8px; opacity:.8; }
37	  .sc.hov { border-color:#222; z-index:2; box-shadow:0 0 8px rgba(59,130,246,.4); }
38	  .sc.dm { opacity:.18; }
39	
40	  .arrow-box { display:flex; flex-direction:column; align-items:center; gap:6px; padding:0 8px; }
41	  .tma-hw-box {
42	    border: 2.5px solid #3b82f6; background: #dbeafe; border-radius: 8px;
43	    padding: 8px 14px; text-align: center;
44	  }
45	  .tma-hw-box .tma-name { font-size: 12px; font-weight: 700; color: #1e40af; }
46	  .tma-hw-box .tma-sub { font-size: 9px; color: #3b82f6; font-weight: 600; }
47	  .arrow-box .arrow-line { color: #3b82f6; font-size: 22px; font-weight: 700; line-height: 1; }
48	  .arrow-box .detail { font-size: 9px; color:var(--dim); font-weight:600; text-align:center; line-height:1.4; }
49	
50	  .arrow-svg { position:absolute; top:0; left:0; width:100%; height:100%; pointer-events:none; z-index:10; overflow:visible; }
51	  .arrow-svg path { fill:none; stroke:#222; stroke-width:1.5; }
52	  .arrow-svg text { font-size:11px; font-weight:600; fill:#222; font-family:inherit; }
53	
54	  .info { max-width:1200px; margin:14px auto 0; background:var(--surface); border:1px solid var(--border);
55	    border-radius:8px; padding:10px 16px; font-size:13px; line-height:1.6; }
56	  .info b { font-weight:700; }
57	  .info .formula { font-family:'SF Mono','Fira Code',monospace; color:var(--accent); font-weight:600; }
58	
59	  .leg { gap:0; margin-top:12px; }
60	
61	  .notes {
62	    max-width:1200px; margin:10px auto 0; padding:0;
63	    list-style:none; display:flex; gap:20px; flex-wrap:wrap;
64	    font-size:12px; color:#475569;
65	  }
66	  .notes li {
67	    display:flex; align-items:baseline; gap:5px;
68	  }
69	  .notes .icon { color:#3b82f6; font-weight:700; flex-shrink:0; }
70	  .notes strong { color:#1e293b; }
71	</style>
72	</head>
73	<body>
74	
75	<h1>TMA: Global to Shared Memory</h1>
76	<div class="sub">One thread issues a 2D copy; the TMA engine moves the full tile and can swizzle it as it writes</div>
77	
78	<div class="controls">
79	  <div><span class="lbl">Swizzle</span>
80	    <div class="bg" id="sw">
81	      <button class="btn" data-v="none">None</button>
82	      <button class="btn on" data-v="128">128B</button>
83	    </div>
84	  </div>
85	  <div><span class="lbl">Row offset</span><div class="bg" id="rc"></div></div>
86	  <div><span class="lbl">Col offset</span><div class="bg" id="cc"></div></div>
87	</div>
88	
89	<div class="main" id="main">
90	  <svg class="arrow-svg" id="arrowsvg"></svg>
91	
92	  <div class="mat-box" style="border-color:#6b7280; background:#f3f4f6;">
93	    <h2>Global Memory</h2>
94	    <div class="dims">16&times;128 fp16 (each cell = 16B = 1&times;8 fp16)</div>
95	    <div class="grid" id="gg"></div>
96	  </div>
97	
98	  <div class="arrow-box">
99	    <div class="tma-hw-box">
100	      <div class="tma-name">TMA Engine</div>
101	      <div class="tma-sub">Data Mover</div>
102	    </div>
103	    <div class="arrow-line">→</div>
104	    <div class="detail" id="tmainfo">cp.async.bulk.tensor.2d<br>+ SWIZZLE_128B</div>
105	  </div>
106	
107	  <div class="mat-box" style="border-color:#8b5cf6; background:#ede9fe;">
108	    <h2 style="color:#5b21b6;">Shared Memory</h2>
109	    <div class="dims" id="sdims">8&times;8 sectors (swizzled)</div>
110	    <div class="grid" id="gs"></div>
111	  </div>
112	</div>
113	
114	<div class="info" id="infobox"></div>
115	
116	<div class="leg">
117	  <div class="leg-row" id="sl"></div>
118	</div>
119	
120	<ul class="notes">
121	  <li><span class="icon">▸</span> <strong>One thread submits the request;</strong> the TMA engine performs the asynchronous copy</li>
122	  <li><span class="icon">▸</span> <strong>Swizzle on arrival</strong> reduces bank conflicts for the target access pattern</li>
123	  <li><span class="icon">▸</span> <strong>Copies in both directions:</strong> load (GMEM→SMEM) and store (SMEM→GMEM)</li>
124	</ul>
125	
126	<script>
127	var BK = ['#5b9bd5','#ed9a3c','#d95555','#45b5a5','#5fb85f','#e0b828','#9d6eb5','#e87888'];
128	
129	var GDR = 16;          // global display rows
130	var GDC = 16;          // global display cols (128 fp16 / 8 per cell)
131	var BOX_R = 8;         // TMA box rows
132	var BOX_C = 8;         // TMA box display cols (128 bytes / 16 bytes per cell)
133	
134	var ST = { sw: '128', row: 0, col: 0, hovR: -1, hovC: -1 };
135	
136	function mk(t, c) { var d = document.createElement(t); if (c) d.className = c; return d; }
137	
138	function draw() {
139	  var useSw = ST.sw === '128';
140	  var rOff = ST.row * BOX_R;
141	  var cOff = ST.col * BOX_C;
142	
143	  // Concrete fp16 coordinates for current offset
144	  var rowCoord = rOff;           // fp16 row
145	  var colCoord = cOff * 8;       // fp16 col (cOff is in sector units, ×8 for fp16)
146	
147	  document.getElementById('tmainfo').innerHTML =
148	    'cp.async.bulk.tensor.2d<br>(row=' + rowCoord + ', col=' + colCoord + ')' +
149	    (useSw ? '<br>+ SWIZZLE_128B' : '');
150	  document.getElementById('sdims').textContent =
151	    BOX_R + '\u00d7' + BOX_C + ' sectors (' + (useSw ? 'swizzled' : 'linear') + ')';
152	
153	  // Info box with tensor map descriptor (concrete strides)
154	  var swName = useSw ? 'CU_TENSOR_MAP_SWIZZLE_128B' : 'CU_TENSOR_MAP_SWIZZLE_NONE';
155	  document.getElementById('infobox').innerHTML =
156	    '<b>TensorMap</b>: <span class="formula">' +
157	    'dtype = f16, globalDim = [128, 16], globalStrides = [256B], ' +
158	    'boxDim = [64, 8], swizzle = ' + swName + '</span><br>' +
159	    '<b>Instruction</b>: <span class="formula">cp.async.bulk.tensor.2d.shared::cta.global.mbarrier::complete_tx::bytes [smem], [tensormap, {' +
160	    colCoord + ', ' + rowCoord + '}], [mbar]</span><br>' +
161	    '<b>Note</b>: TensorMap and PTX list dimensions from innermost to outermost. For the row-major matrix shown here, the order is therefore (col, row).';
162	
163	  // Global memory: 16 rows x 16 cells
164	  var gg = document.getElementById('gg');
165	  gg.innerHTML = '';
166	  gg.style.gridTemplateColumns = 'repeat(' + GDC + ', 18px)';
167	  for (var r = 0; r < GDR; r++) {
168	    for (var c = 0; c < GDC; c++) {
169	      var d = mk('div', 'gc');
170	      d.style.width = '18px';
171	      d.style.height = '18px';
172	      var inBox = (r >= rOff && r < rOff + BOX_R && c >= cOff && c < cOff + BOX_C);
173	      if (inBox) {
174	        d.classList.add('inbox');
175	        var lr = r - rOff, lc = c - cOff;
176	        d.dataset.lr = lr;
177	        d.dataset.lc = lc;
178	        if (ST.hovR === lr && ST.hovC === lc) d.classList.add('hov');
179	      } else {
180	        d.classList.add('idle');
181	      }
182	      gg.appendChild(d);
183	    }
184	  }
185	
186	  // Shared memory: 8 rows x 8 cols with row/col headers (swizzle-atom style)
187	  var gs = document.getElementById('gs');
188	  gs.innerHTML = '';
189	  var csz = 46;
190	  gs.style.gridTemplateColumns = '24px repeat(' + BOX_C + ',' + csz + 'px)';
191	
192	  // Column headers (physical sectors)
193	  gs.appendChild(mk('div', 'hdr'));
194	  for (var s = 0; s < BOX_C; s++) {
195	    var h = mk('div', 'hdr');
196	    h.textContent = 's' + s;
197	    gs.appendChild(h);
198	  }
199	
200	  // Rows
201	  for (var r = 0; r < BOX_R; r++) {
202	    var rl = mk('div', 'rl');
203	    rl.textContent = 'r' + r;
204	    gs.appendChild(rl);
205	    for (var s = 0; s < BOX_C; s++) {
206	      var d = mk('div', 'sc');
207	      d.style.width = csz + 'px';
208	      d.style.height = '34px';
209	      d.style.background = BK[s % 8];
210	      d.dataset.sr = r;
211	      d.dataset.ss = s;
212	      // Logical column: what global data is at physical sector s in row r
213	      var logCol = useSw ? (s ^ r) : s;
214	      d.innerHTML = '<span class="cv">' + logCol + '</span><span class="ca">@' + (r * 128 + s * 16) + '</span>';
215	      if (ST.hovR >= 0) {
216	        var destSec = useSw ? (ST.hovC ^ ST.hovR) : ST.hovC;
217	        if (r === ST.hovR && s === destSec) d.classList.add('hov');
218	        else d.classList.add('dm');
219	      }
220	      gs.appendChild(d);
221	    }
222	  }
223	
224	  // Arrow
225	  drawArrow();
226	
227	  // Legend
228	  var sl = document.getElementById('sl');
229	  sl.innerHTML = '';
230	  for (var i = 0; i < 8; i++) {
231	    var li = mk('div', 'li');
232	    var sw = mk('div', 'swtch');
233	    sw.style.background = BK[i];
234	    li.appendChild(sw);
235	    li.appendChild(document.createTextNode('sector ' + i));
236	    sl.appendChild(li);
237	  }
238	  var sep = mk('div', 'leg-sep');
239	  sl.appendChild(sep);
240	  var cv = mk('div', 'li');
241	  cv.textContent = 'cell value = source-tile logical column  |  @N = SMEM byte offset';
242	  sl.appendChild(cv);
243	}
244	
245	function drawArrow() {
246	  var svg = document.getElementById('arrowsvg');
247	  svg.innerHTML = '';
248	  if (ST.hovR < 0) return;
249	
250	  var mainEl = document.getElementById('main');
251	  var gCell = document.querySelector('.gc.hov');
252	  var sCell = document.querySelector('.sc.hov');
253	  if (!gCell || !sCell) return;
254	
255	  var pr = mainEl.getBoundingClientRect();
256	  var ga = gCell.getBoundingClientRect();
257	  var sa = sCell.getBoundingClientRect();
258	  var x1 = ga.left + ga.width / 2 - pr.left;
259	  var y1 = ga.top + ga.height / 2 - pr.top;
260	  var x2 = sa.left + sa.width / 2 - pr.left;
261	  var y2 = sa.top + sa.height / 2 - pr.top;
262	  var mx = (x1 + x2) / 2;
263	  var my = Math.min(y1, y2) - 40;
264	
265	  var ns = 'http://www.w3.org/2000/svg';
266	  var defs = document.createElementNS(ns, 'defs');
267	  var marker = document.createElementNS(ns, 'marker');
268	  marker.setAttribute('id', 'ah');
269	  marker.setAttribute('markerWidth', '8');
270	  marker.setAttribute('markerHeight', '6');
271	  marker.setAttribute('refX', '7');
272	  marker.setAttribute('refY', '3');
273	  marker.setAttribute('orient', 'auto');
274	  var poly = document.createElementNS(ns, 'polygon');
275	  poly.setAttribute('points', '0 0, 8 3, 0 6');
276	  poly.setAttribute('fill', '#222');
277	  marker.appendChild(poly);
278	  defs.appendChild(marker);
279	  svg.appendChild(defs);
280	
281	  var path = document.createElementNS(ns, 'path');
282	  path.setAttribute('d', 'M' + x1 + ',' + y1 + ' Q' + mx + ',' + my + ' ' + x2 + ',' + y2);
283	  path.setAttribute('marker-end', 'url(#ah)');
284	  svg.appendChild(path);
285	
286	  var useSw = ST.sw === '128';
287	  if (useSw) {
288	    var tx = document.createElementNS(ns, 'text');
289	    tx.setAttribute('x', mx);
290	    tx.setAttribute('y', my - 4);
291	    tx.setAttribute('text-anchor', 'middle');
292	    tx.textContent = 'col ' + ST.hovC + ' XOR row ' + ST.hovR + ' = sector ' + ((ST.hovC ^ ST.hovR) % 8);
293	    svg.appendChild(tx);
294	  }
295	}
296	
297	(function init() {
298	  document.getElementById('sw').onclick = function(e) {
299	    var b = e.target.closest('.btn'); if (!b) return;
300	    ST.sw = b.dataset.v;
301	    document.querySelectorAll('#sw .btn').forEach(function(x) { x.classList.remove('on'); });
302	    b.classList.add('on');
303	    ST.hovR = -1; ST.hovC = -1;
304	    draw();
305	  };
306	
307	  // Row offset buttons: 0, 8
308	  var rc = document.getElementById('rc');
309	  for (var i = 0; i < GDR / BOX_R; i++) {
310	    var b = mk('button', 'btn' + (i === 0 ? ' on' : ''));
311	    b.textContent = i * BOX_R;
312	    b.onclick = (function(v) { return function() {
313	      ST.row = v;
314	      rc.querySelectorAll('.btn').forEach(function(x) { x.classList.remove('on'); });
315	      this.classList.add('on');
316	      ST.hovR = -1; ST.hovC = -1;
317	      draw();
318	    }; })(i);
319	    rc.appendChild(b);
320	  }
321	
322	  // Col offset buttons: 0, 64
323	  var cc = document.getElementById('cc');
324	  for (var i = 0; i < GDC / BOX_C; i++) {
325	    var b = mk('button', 'btn' + (i === 0 ? ' on' : ''));
326	    b.textContent = i * BOX_C * 8;
327	    b.onclick = (function(v) { return function() {
328	      ST.col = v;
329	      cc.querySelectorAll('.btn').forEach(function(x) { x.classList.remove('on'); });
330	      this.classList.add('on');
331	      ST.hovR = -1; ST.hovC = -1;
332	      draw();
333	    }; })(i);
334	    cc.appendChild(b);
335	  }
336	
337	  // Hover handlers on the main container (event delegation)
338	  var mainEl = document.getElementById('main');
339	  mainEl.addEventListener('mouseenter', function(e) {
340	    var cell = e.target.closest('.gc.inbox');
341	    if (!cell) return;
342	    ST.hovR = +cell.dataset.lr;
343	    ST.hovC = +cell.dataset.lc;
344	    draw();
345	  }, true);
346	  mainEl.addEventListener('mouseleave', function(e) {
347	    var cell = e.target.closest('.gc.inbox');
348	    if (!cell) return;
349	    ST.hovR = -1;
350	    ST.hovC = -1;
351	    draw();
352	  }, true);
353	
354	  draw();
355	})();
356	</script>
357	</body>
358	</html>
